import {itemHTML,offerHTML,matches} from './render.mjs';
const data=JSON.parse(document.querySelector('#site-data').textContent),current=data.issues.find(d=>d.digest_id===data.current);let filter='all';
const search=document.querySelector('#search'),scope=document.querySelector('#scope');
function render(){const q=search.value.trim(),issues=q&&scope.value==='all'?data.issues:[current];const selected=issues.flatMap(d=>d.items).filter(i=>(filter==='column'?i.category!=='news':filter==='all'||i.group===filter)&&matches(i,q));document.querySelector('#featured').hidden=!!q||filter!=='all';document.querySelector('#news-list').innerHTML=selected.map((i,n)=>itemHTML(i,n)).join('')||'<p class="empty">没有匹配资讯。</p>';document.querySelector('#search-status').textContent=q?`搜索 ${issues.length} 期，共 ${selected.length} 项`:'';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});document.querySelector('#offer-list').innerHTML=data.offers.filter(o=>!q||JSON.stringify(o).toLowerCase().includes(q.toLowerCase())).map(offerHTML).join('')||'<p class="empty">没有匹配免费资源。</p>';}
search.addEventListener('input',render);scope.addEventListener('change',render);document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;render()}));document.querySelector('#clear').addEventListener('click',()=>{search.value='';filter='all';scope.value='all';render();search.focus()});
function setTheme(value,persist=true){const theme=['a','b','c'].includes(value)?value:'b';document.documentElement.dataset.theme=theme;document.body.className='style-'+theme;const link=document.querySelector('#theme-css');if(link)link.setAttribute('href',(data.prefix||'')+'assets/theme-'+theme+'.css');document.querySelectorAll('[data-theme-choice]').forEach(b=>{b.classList.toggle('active',b.dataset.themeChoice===theme);b.setAttribute('aria-pressed',String(b.dataset.themeChoice===theme))});if(persist)try{localStorage.setItem('ai-daily-theme',theme)}catch(e){}}
if(document.documentElement&&document.body){setTheme(document.documentElement.dataset.theme||'b',false);document.querySelectorAll('[data-theme-choice]').forEach(b=>b.addEventListener('click',()=>setTheme(b.dataset.themeChoice)))}
const lead=document.querySelector('.read-lead'),details=document.querySelector('.hero-details');if(lead&&details)lead.addEventListener('click',()=>{details.hidden=!details.hidden;lead.setAttribute('aria-expanded',String(!details.hidden));lead.innerHTML=(details.hidden?'阅读全文':'收起全文')+' <span>↗</span>'});
if(typeof matchMedia==='function'&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&matchMedia('(pointer:fine)').matches){const art=document.querySelector('.hero-art');if(art){art.addEventListener('pointermove',e=>{const r=art.getBoundingClientRect();art.style.setProperty('--rx',((e.clientY-r.top)/r.height-.5)*-8+'deg');art.style.setProperty('--ry',((e.clientX-r.left)/r.width-.5)*8+'deg')});art.addEventListener('pointerleave',()=>{art.style.setProperty('--rx','0deg');art.style.setProperty('--ry','0deg')})}}
render();
